import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { InMemoryQueue } from "../src/queue/broker.ts";
import { Consumer } from "../src/queue/consumer.ts";
import { regenerateAll, thumbnailHandler, type BlobStore } from "../src/thumbnails/worker.ts";

// Blob store that yields like a network call and can fail the next N writes.
function memoryBlobs(photoIds: string[]) {
    const data = new Map<string, Uint8Array>(photoIds.map((id) => [`originals/${id}`, new Uint8Array(2000)]));
    const state = { failNextPuts: 0 };
    const blobs: BlobStore = {
        async get(key) {
            await tick();
            return data.get(key) ?? null;
        },
        async put(key, bytes) {
            await tick();
            if (state.failNextPuts > 0) {
                state.failNextPuts--;
                throw new Error("503 SlowDown");
            }
            data.set(key, bytes);
        },
    };
    const thumbs = (id: string) => [...data.keys()].filter((k) => k.startsWith(`thumbs/${id}/`)).length;
    return { blobs, state, thumbs };
}

const resize = async (img: Uint8Array, width: number) => img.slice(0, width);

test("every queued photo gets all its thumbnails and the queue ends empty", async () => {
    const queue = new InMemoryQueue();
    const { blobs, thumbs } = memoryBlobs(["p1", "p2", "p3", "p4", "p5"]);
    const result = await regenerateAll(queue, blobs, resize, ["p1", "p2", "p3", "p4", "p5"], 2);
    assert.equal(result.processed, 5);
    assert.deepEqual(["p1", "p2", "p3", "p4", "p5"].map(thumbs), [3, 3, 3, 3, 3]);
    assert.deepEqual(queue.depth(), { waiting: 0, inFlight: 0 });
});

test("never more than `concurrency` renders run at once", async () => {
    const queue = new InMemoryQueue();
    for (let i = 0; i < 12; i++) await queue.send(`job-${i}`);
    let running = 0;
    let peak = 0;
    const consumer = new Consumer(queue, async () => {
        peak = Math.max(peak, ++running);
        await tick();
        await tick();
        running--;
    }, 3);
    await consumer.drain();
    assert.equal(peak, 3);
    assert.equal(consumer.stats().processed, 12);
});

test("a photo whose upload failed once is retried and still gets thumbnails", async () => {
    const queue = new InMemoryQueue();
    const { blobs, state, thumbs } = memoryBlobs(["p1", "p2"]);
    state.failNextPuts = 1;
    const result = await regenerateAll(queue, blobs, resize, ["p1", "p2"], 2);
    assert.deepEqual([thumbs("p1"), thumbs("p2")], [3, 3]);
    assert.equal(result.failedAttempts, 1);
});

test("jobs that can never succeed are dropped instead of retried", async () => {
    const queue = new InMemoryQueue();
    const { blobs } = memoryBlobs(["p1"]);
    await queue.send("{not json");
    const result = await regenerateAll(queue, blobs, resize, ["p1", "deleted-photo"]);
    assert.deepEqual(result.skipped, ["{not json", "deleted-photo"]);
    assert.equal(result.processed, 3);
    assert.deepEqual(queue.depth(), { waiting: 0, inFlight: 0 });
});

test("a burst of failures doesn't stop the consumer from taking new work", async () => {
    const queue = new InMemoryQueue();
    for (let i = 0; i < 6; i++) await queue.send(`job-${i}`);
    let failuresLeft = 4;
    const errors: string[] = [];
    const consumer = new Consumer(queue, async () => {
        await tick();
        if (failuresLeft-- > 0) throw new Error("render farm unavailable");
    }, 2, (err) => errors.push((err as Error).message));

    for (let i = 0; i < 40; i++) {
        await consumer.pollOnce();
        await tick();
    }
    console.log("after 40 polls:", consumer.stats(), queue.depth());
    assert.equal(errors.length, 4);
    assert.deepEqual(consumer.stats(), { inFlight: 0, processed: 6, failed: 4 });
});

test("failed messages are handed back to the queue, not deleted", async () => {
    const queue = new InMemoryQueue();
    await queue.send("job");
    let attempts = 0;
    const consumer = new Consumer(queue, async () => {
        if (++attempts === 1) throw new Error("timeout");
    }, 1);
    await consumer.pollOnce();
    await tick();
    assert.deepEqual(queue.depth(), { waiting: 1, inFlight: 0 });
    const [redelivered] = await queue.receive(1);
    assert.equal(redelivered.receiveCount, 2);
});

test("a backfill with intermittent storage errors finishes every photo", async () => {
    const ids = Array.from({ length: 10 }, (_, i) => `photo-${i}`);
    const queue = new InMemoryQueue();
    const { blobs, state, thumbs } = memoryBlobs(ids);
    state.failNextPuts = 5;
    const result = await regenerateAll(queue, blobs, resize, ids, 4);
    assert.equal(result.processed, 10);
    assert.ok(ids.every((id) => thumbs(id) === 3));
});
